patch:
diff --git a/sql/set_var.cc b/sql/set_var.cc
index 629a1fd9d290..d8193c788a01 100644
--- a/sql/set_var.cc
+++ b/sql/set_var.cc
@@ -875,7 +875,7 @@ int set_var::resolve(THD *thd)
     my_error(err, MYF(0), var->name.str);
     DBUG_RETURN(-1);
   }
-  if (is_global_persist())
+  if (type == OPT_GLOBAL || type == OPT_PERSIST)
   {
     /* Either the user has SUPER_ACL or she has SYSTEM_VARIABLES_ADMIN */
     Security_context *sctx= thd->security_context();
@@ -886,16 +886,22 @@ int set_var::resolve(THD *thd)
                "SUPER or SYSTEM_VARIABLES_ADMIN");
       DBUG_RETURN(1);
     }
-    if (type == OPT_PERSIST_ONLY)
+  }
+  if (type == OPT_PERSIST_ONLY)
+  {
+    Security_context *sctx= thd->security_context();
+    /*
+     user should have both SYSTEM_VARIABLES_ADMIN and "PERSIST_RO_VARIABLES_ADMIN"
+     privilege to persist read only variables
+    */
+    if (!(sctx->has_global_grant(
+          STRING_WITH_LEN("SYSTEM_VARIABLES_ADMIN")).first &&
+          sctx->has_global_grant(
+          STRING_WITH_LEN("PERSIST_RO_VARIABLES_ADMIN")).first))
     {
-      if (!sctx->check_access(SUPER_ACL) &&
-          !sctx->has_global_grant(
-            STRING_WITH_LEN("PERSIST_RO_VARIABLES_ADMIN")).first)
-      {
-        my_error(ER_SPECIFIC_ACCESS_DENIED_ERROR, MYF(0),
-                 "SUPER or PERSIST_RO_VARIABLES_ADMIN");
-        DBUG_RETURN(1);
-      }
+      my_error(ER_PERSIST_ONLY_ACCESS_DENIED_ERROR, MYF(0),
+               "SYSTEM_VARIABLES_ADMIN and PERSIST_RO_VARIABLES_ADMIN");
+      DBUG_RETURN(1);
     }
   }
   /* value is a NULL pointer if we are using SET ... = DEFAULT */
@@ -975,8 +981,10 @@ int set_var::light_check(THD *thd)
     return 1;

   if ((type == OPT_PERSIST_ONLY) &&
-      !(sctx->check_access(SUPER_ACL) ||
-        sctx->has_global_grant(STRING_WITH_LEN("PERSIST_RO_VARIABLES_ADMIN")).first))
+      !(sctx->has_global_grant(
+        STRING_WITH_LEN("PERSIST_RO_VARIABLES_ADMIN")).first &&
+        sctx->has_global_grant(
+        STRING_WITH_LEN("SYSTEM_VARIABLES_ADMIN")).first))
     return 1;

   if (value && ((!value->fixed && value->fix_fields(thd, &value)) ||
diff --git a/sql/share/errmsg-utf8.txt b/sql/share/errmsg-utf8.txt
index 3642decc2f94..ae01e76f83a6 100644
--- a/sql/share/errmsg-utf8.txt
+++ b/sql/share/errmsg-utf8.txt
@@ -10793,6 +10793,9 @@ ER_MANDATORY_ROLE
 ER_MISSING_TABLESPACE_FILE
   eng "Tablespace '%.192s' does not have a file named '%.192s'"

+ER_PERSIST_ONLY_ACCESS_DENIED_ERROR 42000
+  eng "Access denied; you need %-.128s privileges for this operation"
+
 #
 #  End of 8.0 error messages.
 #

test_patch:
diff --git a/mysql-test/r/read_only_persisted_variables.result b/mysql-test/r/read_only_persisted_variables.result
index 4bb53876856b..b7529d8d53fd 100644
--- a/mysql-test/r/read_only_persisted_variables.result
+++ b/mysql-test/r/read_only_persisted_variables.result
@@ -210,23 +210,26 @@ ERROR 42000: Access denied; you need (at least one of) the SUPER or SYSTEM_VARIA
 SET PERSIST max_heap_table_size=999424;
 ERROR 42000: Access denied; you need (at least one of) the SUPER or SYSTEM_VARIABLES_ADMIN privilege(s) for this operation
 SET PERSIST_ONLY ft_query_expansion_limit=80;
-ERROR 42000: Access denied; you need (at least one of) the SUPER or SYSTEM_VARIABLES_ADMIN privilege(s) for this operation
+ERROR 42000: Access denied; you need SYSTEM_VARIABLES_ADMIN and PERSIST_RO_VARIABLES_ADMIN privileges for this operation
 GRANT SYSTEM_VARIABLES_ADMIN ON *.* TO wl9787;
 SET GLOBAL sort_buffer_size=256000;
 SET PERSIST max_heap_table_size=999424;
 SET PERSIST_ONLY ft_query_expansion_limit=80;
-ERROR 42000: Access denied; you need (at least one of) the SUPER or PERSIST_RO_VARIABLES_ADMIN privilege(s) for this operation
+ERROR 42000: Access denied; you need SYSTEM_VARIABLES_ADMIN and PERSIST_RO_VARIABLES_ADMIN privileges for this operation
 GRANT PERSIST_RO_VARIABLES_ADMIN ON *.* TO wl9787;
 SET PERSIST_ONLY ft_query_expansion_limit=80;
 # revoke SYSTEM_VARIABLES_ADMIN
 REVOKE SYSTEM_VARIABLES_ADMIN ON *.* FROM wl9787;
 # persisting static variables needs both SYSTEM_VARIABLES_ADMIN
 SET PERSIST_ONLY ft_query_expansion_limit=80;
-ERROR 42000: Access denied; you need (at least one of) the SUPER or SYSTEM_VARIABLES_ADMIN privilege(s) for this operation
+ERROR 42000: Access denied; you need SYSTEM_VARIABLES_ADMIN and PERSIST_RO_VARIABLES_ADMIN privileges for this operation
 REVOKE PERSIST_RO_VARIABLES_ADMIN  ON *.* FROM wl9787;
-GRANT ALL ON *.* TO wl9787;
-# persisting static variables needs SUPER access
+GRANT SUPER ON *.* TO wl9787;
+Warnings:
+Warning	1287	The SUPER privilege identifier is deprecated
+# persisting static variables does not need SUPER access
 SET PERSIST_ONLY ft_query_expansion_limit=80;
+ERROR 42000: Access denied; you need SYSTEM_VARIABLES_ADMIN and PERSIST_RO_VARIABLES_ADMIN privileges for this operation
 # reset persisted variables
 RESET PERSIST;
 # test reset on readonly persisted variables
diff --git a/mysql-test/t/read_only_persisted_variables.test b/mysql-test/t/read_only_persisted_variables.test
index b8dca0cce3c0..4c59d0e70796 100644
--- a/mysql-test/t/read_only_persisted_variables.test
+++ b/mysql-test/t/read_only_persisted_variables.test
@@ -228,7 +228,7 @@ CREATE USER wl9787;
 SET GLOBAL sort_buffer_size=256000;
 --error ER_SPECIFIC_ACCESS_DENIED_ERROR
 SET PERSIST max_heap_table_size=999424;
---error ER_SPECIFIC_ACCESS_DENIED_ERROR
+--error ER_PERSIST_ONLY_ACCESS_DENIED_ERROR
 SET PERSIST_ONLY ft_query_expansion_limit=80;

 --connection default
@@ -237,7 +237,7 @@ GRANT SYSTEM_VARIABLES_ADMIN ON *.* TO wl9787;
 --connection con1
 SET GLOBAL sort_buffer_size=256000;
 SET PERSIST max_heap_table_size=999424;
---error ER_SPECIFIC_ACCESS_DENIED_ERROR
+--error ER_PERSIST_ONLY_ACCESS_DENIED_ERROR
 SET PERSIST_ONLY ft_query_expansion_limit=80;

 --connection default
@@ -253,15 +253,16 @@ REVOKE SYSTEM_VARIABLES_ADMIN ON *.* FROM wl9787;
 --connection con1
 --echo # persisting static variables needs both SYSTEM_VARIABLES_ADMIN
        # and PERSIST_RO_VARIABLES_ADMIN
---error ER_SPECIFIC_ACCESS_DENIED_ERROR
+--error ER_PERSIST_ONLY_ACCESS_DENIED_ERROR
 SET PERSIST_ONLY ft_query_expansion_limit=80;

 --connection default
 REVOKE PERSIST_RO_VARIABLES_ADMIN  ON *.* FROM wl9787;
-GRANT ALL ON *.* TO wl9787;
+GRANT SUPER ON *.* TO wl9787;

 --connection con1
---echo # persisting static variables needs SUPER access
+--echo # persisting static variables does not need SUPER access
+--error ER_PERSIST_ONLY_ACCESS_DENIED_ERROR
 SET PERSIST_ONLY ft_query_expansion_limit=80;

 --connection default
